/**
 * distractorLabels.ts — ui-p1-panels 刀 #4: translate the machine-facing
 * distractor `category` / `subtype` enum strings (V0 schema, generated by
 * the paper-intelligence prompt — see `prompts/paper-intelligence-v0.md`)
 * into teacher-facing Chinese labels.
 *
 * `category` is a closed 3-value enum (per the prompt spec §干扰项分析):
 * `detail_word_misleading` / `not_mentioned` / `common_sense_distractor`.
 * `subtype` is only defined under `detail_word_misleading` and is NOT a
 * closed enum in the schema — the prompt explicitly says it "含所有
 * subtype" without enumerating a fixed list. The 5 values below are every
 * subtype observed in the one report fixture the repo ships
 * (`app/public/reports/paper-intelligence/paper-2024-xkb1-reading/report.json`)
 * plus the prompt's worked example. Any subtype outside this dictionary
 * still gets a readable (non-raw-snake_case) fallback rather than being
 * shown naked, per the audit's "不许漏译裸奔" instruction.
 */

const CATEGORY_LABELS: Record<string, string> = {
  detail_word_misleading: '细节词误导',
  not_mentioned: '文中未提及',
  common_sense_distractor: '常识型干扰',
}

const SUBTYPE_LABELS: Record<string, string> = {
  object_mismatch: '对象错位',
  opposite_direction: '正话反说',
  scope_shift: '范围偏移',
  half_right_half_wrong: '半对半错',
  cause_effect_shift: '因果错位',
}

/** Humanize an unrecognized snake_case token so nothing renders raw. */
function humanizeUnknown(value: string): string {
  return value.trim().replace(/_/g, ' ')
}

export function distractorCategoryLabel(category: string): string {
  return CATEGORY_LABELS[category] ?? humanizeUnknown(category)
}

export function distractorSubtypeLabel(subtype: string): string {
  return SUBTYPE_LABELS[subtype] ?? humanizeUnknown(subtype)
}
